"""Idempotent file writer for emitter output.

Reads existing target files, computes diffs, writes only when content changes,
and stamps each generated file with a comment so users can tell what Harness owns.
"""

from __future__ import annotations

import difflib
import shutil
from dataclasses import dataclass, field
from pathlib import Path


@dataclass
class WriteResult:
    written: list[Path] = field(default_factory=list)
    unchanged: list[Path] = field(default_factory=list)
    skipped_dry_run: list[Path] = field(default_factory=list)
    # Files we deliberately did NOT touch because they already exist and are
    # team-owned (e.g. CLAUDE.md, `<framework>-patterns/SKILL.md`). Surface in
    # the generate summary so users know Harness is honouring their authoring.
    preserved: list[Path] = field(default_factory=list)
    diffs: dict[Path, str] = field(default_factory=dict)


def _ensure_parent(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)


def write_file(
    path: Path,
    content: str,
    *,
    dry_run: bool = False,
    diff: bool = False,
    executable: bool = False,
    preserve_existing: bool = False,
    result: WriteResult | None = None,
) -> WriteResult:
    """Write `content` to `path` if and only if it differs from existing content.

    With `dry_run=True`, no writes occur but the result still records what would change.
    With `diff=True`, the unified diff against existing content is captured into
    `result.diffs`.
    With `preserve_existing=True`, if `path` already exists we make NO change —
    the file is team-owned (CLAUDE.md, `<framework>-patterns/SKILL.md`, etc.) and
    Harness must not clobber human edits on regenerate. The path is logged into
    `result.preserved` so the summary can surface it.
    """
    result = result or WriteResult()

    existing: str | None = path.read_text(encoding="utf-8") if path.exists() and path.is_file() else None

    if preserve_existing and existing is not None:
        result.preserved.append(path)
        return result

    if existing == content:
        result.unchanged.append(path)
        return result

    if diff:
        old_lines = (existing or "").splitlines(keepends=True)
        new_lines = content.splitlines(keepends=True)
        result.diffs[path] = "".join(
            difflib.unified_diff(
                old_lines, new_lines, fromfile=f"{path} (old)", tofile=f"{path} (new)"
            )
        )

    if dry_run:
        result.skipped_dry_run.append(path)
        return result

    _ensure_parent(path)
    path.write_text(content, encoding="utf-8")
    if executable:
        # On Windows chmod only honours the read-only flag — the POSIX execute bits
        # are silently ignored (and aren't needed; hooks run via `node script.mjs`).
        # This pairs with the F-012 linter check, which is skipped on Windows for the
        # same reason. The call is a harmless no-op there.
        path.chmod(0o755)
    result.written.append(path)
    return result


def copy_file(
    src: Path,
    dst: Path,
    *,
    dry_run: bool = False,
    executable: bool = False,
    result: WriteResult | None = None,
) -> WriteResult:
    """Copy a static (non-Jinja) file from source layer to output."""
    return write_file(
        dst,
        src.read_text(encoding="utf-8"),
        dry_run=dry_run,
        executable=executable,
        result=result,
    )


def remove_file(path: Path, *, dry_run: bool = False, result: WriteResult | None = None) -> WriteResult:
    """Remove a file. Used by the writer when a previously-generated file is no
    longer produced (so harness updates don't leave orphans)."""
    result = result or WriteResult()
    if not path.exists():
        return result
    if dry_run:
        result.skipped_dry_run.append(path)
        return result
    path.unlink()
    result.written.append(path)
    return result


def remove_empty_dirs(root: Path, *, dry_run: bool = False) -> None:
    """Remove empty directories under `root`, depth-first. Idempotent."""
    if not root.exists() or not root.is_dir():
        return
    for child in sorted(root.rglob("*"), key=lambda p: -len(p.parts)):
        if child.is_dir() and not any(child.iterdir()) and not dry_run:
            shutil.rmtree(child, ignore_errors=True)
